import { describe, expect, it } from "vitest";

import {
  SanitizingAuditService,
  sanitizeAuditReason,
} from "../../src/modules/tournament-foundation/audit.port.js";

// Shape of a raw 64-hex activation token generated by
// modules/roster/activation.service.ts (randomBytes(32).toString("hex")).
const ACTIVATION_TOKEN = "9f2c4b8a1d3e5f70a2c4b6d8e0f2a4c6b8d0e2f4a6c8d0e2f4b6d8a0c2e4f6b8";
const HEX_RE = /^[0-9a-f]{64}$/;

describe("audit.port — sanitizeAuditReason (BR-41, T077)", () => {
  it("redacts a reason that is a raw 64-hex activation token", () => {
    expect(HEX_RE.test(ACTIVATION_TOKEN)).toBe(true);
    expect(sanitizeAuditReason(ACTIVATION_TOKEN)).toBe("[REDACTED]");
  });

  it("redacts mixed Vietnamese text that embeds a 64-hex token", () => {
    const reason = `Kích hoạt thí sinh SV001 với mã ${ACTIVATION_TOKEN} do mất thư mời.`;
    expect(sanitizeAuditReason(reason)).toBe("[REDACTED]");
  });

  it("does not redact ordinary Vietnamese reason text", () => {
    const reason = "Hủy giải do đơn vị chủ quản rút yêu cầu tổ chức.";
    expect(sanitizeAuditReason(reason)).toBe(reason);
  });

  it("does not redact short hex values below 32 characters", () => {
    const colorCode = "#18795B";
    expect(sanitizeAuditReason(`Đổi màu nhấn sang ${colorCode} theo thiết kế Robot Lab.`)).toBe(
      `Đổi màu nhấn sang ${colorCode} theo thiết kế Robot Lab.`
    );

    const shortId = "a1b2c3d4e5f6";
    expect(sanitizeAuditReason(`Ghim digest ${shortId} cho cấu hình v4.`)).toBe(
      `Ghim digest ${shortId} cho cấu hình v4.`
    );
  });

  it("does not redact dashed UUIDs or underscore-prefixed context refs (no 32-char hex run)", () => {
    const uuid = "11111111-2222-4333-8444-555555555555";
    expect(sanitizeAuditReason(`Nhận biên lai ${uuid} từ runtime.`)).toBe(
      `Nhận biên lai ${uuid} từ runtime.`
    );

    const contextRef = "brt_aaaaaaaaaaaaaaaaaaaaaaaa";
    expect(sanitizeAuditReason(`Đối chiếu target ${contextRef} trước khi kiểm tra lại.`)).toBe(
      `Đối chiếu target ${contextRef} trước khi kiểm tra lại.`
    );
  });

  it("stores [REDACTED] when the service persists a reason containing a raw token", () => {
    const service = new SanitizingAuditService();
    service.append({
      actorUserId: "admin-1",
      actorRole: "ADMIN",
      action: "TOURNAMENT_ACTIVATE_PARTICIPANT",
      targetType: "TOURNAMENT",
      targetId: "t-1",
      reason: `Mã kích hoạt: ${ACTIVATION_TOKEN}`,
    });

    const [record] = service.list({ targetId: "t-1" });
    expect(record?.reason).toBe("[REDACTED]");
  });
});
